from PIL import Image
from scipy import ndimage as ndi
R=json.load(open('/app/skeleton_routes.json')); T=np.array(Image.open('/app/target.png').convert('L'))<80; D=ndi.distance_transform_edt(T)
boxes={'惠':(600,70,890,455,9),'和':(80,130,450,400,6),'風':(590,580,925,925,6),'暢':(100,575,435,940,7)}
def belongs(p,b):x,y=p;return b[0]<=x<b[2] and b[1]<=y<b[3]
def raster(inds,mult):
 A=np.zeros_like(T)
 for i in inds:
  path=np.array(R[i],float)
  # interpolate pixel-spaced samples
  for a,b in zip(path[:-1],path[1:]):
   L=np.linalg.norm(b-a); n=max(1,int(np.ceil(L)))
   for q in a+(b-a)*(np.arange(n+1)[:,None]/n):
    x,y=np.rint(q).astype(int); rad=max(1.,D[y,x]*mult); rr=int(np.ceil(rad)); y0=max(0,y-rr);y1=min(1024,y+rr+1);x0=max(0,x-rr);x1=min(1024,x+rr+1); yy,xx=np.ogrid[y0:y1,x0:x1]; A[y0:y1,x0:x1]|=((yy-y)**2+(xx-x)**2<=rad**2)
 return A
for mult in [.75,.9,1.0]:
 sel=[]
 for ch,b in boxes.items():
  cand=[]
  for i,p in enumerate(R):
   if any(belongs(q,b) for q in p): cand.append((len(p),i))
  cand.sort(reverse=True); pick=[i for _,i in cand[:b[4]]]; sel+=pick
  print(ch,'len',sum(next(l for l,j in cand if j==i) for i in pick),'selected',pick)
 A=raster(sel,mult); inter=(A&T).sum();print('mult',mult,'IoU',inter/(A|T).sum(),'rec',inter/T.sum(),'prec',inter/A.sum(),'area',A.sum())
